let db = {};
const page = document.body.dataset.page;
const $ = (selector, root=document) => root.querySelector(selector);
const $$ = (selector, root=document) => [...root.querySelectorAll(selector)];
const uid = prefix => prefix + Date.now().toString(36) + Math.random().toString(36).slice(2,6);
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
const get = (key, id) => db[key].find(item => item.id === id);
const className = id => get('classes', id)?.name || 'Unassigned';
const subjectName = id => get('subjects', id)?.name || 'Unassigned';
const teacherName = id => get('teachers', id)?.name || 'Unassigned';
const studentName = id => get('students', id)?.name || 'Unknown student';
const today = () => new Date().toISOString().slice(0,10);
function ageFromDob(dob) { if (!dob) return '-'; const birth=new Date(dob+'T00:00:00'), now=new Date(); let age=now.getFullYear()-birth.getFullYear(); if (now.getMonth()<birth.getMonth() || (now.getMonth()===birth.getMonth() && now.getDate()<birth.getDate())) age--; return age; }
function save(key) { localStorage.setItem('schoolos_' + key, JSON.stringify(db[key])); }
function saveAll() { KEYS.forEach(save); }
function restoreMissingStudents() { const currentIds=new Set(db.students.map(student=>student.studentId)); const missing=seed.students.filter(student=>!currentIds.has(student.studentId)); if(!missing.length)return; db.students.push(...structuredClone(missing)); save('students'); }
function restoreMissingUsers() { const usernames=new Set(db.users.map(user=>user.username.toLowerCase())); const missing=seed.users.filter(user=>!usernames.has(user.username.toLowerCase())); if(!missing.length)return; db.users.push(...structuredClone(missing)); save('users'); }
function initData() { const storedSettings=JSON.parse(localStorage.getItem('schoolos_settings')||'null'); const legacy=storedSettings?.schoolName==='Northstar Academy'; KEYS.forEach(key => { const raw=localStorage.getItem('schoolos_'+key); db[key]=raw&&!legacy?JSON.parse(raw):structuredClone(seed[key]); }); restoreMissingStudents(); restoreMissingUsers(); if(legacy) saveAll(); }
function currentUser() { try { return JSON.parse(sessionStorage.getItem('schoolos_session')||'null'); } catch { return null; } }
function isRole(...roles) { return roles.includes(currentUser()?.role); }
function logActivity(text) { const user=currentUser()||{name:'System',role:'System'}; const date=new Date().toISOString(); db.activities.unshift({text, date}); db.activities = db.activities.slice(0,12); db.auditLogs.unshift({id:uid('audit'),actor:user.name,role:user.role,action:text,date}); db.auditLogs=db.auditLogs.slice(0,200); save('activities'); save('auditLogs'); }
function showToast(message) { const old = $('.toast'); if (old) old.remove(); const el = document.createElement('div'); el.className='toast'; el.textContent=message; document.body.append(el); setTimeout(()=>el.remove(), 2800); }
function formatDate(date) { if (!date) return '-'; return new Intl.DateTimeFormat('en',{month:'short',day:'numeric',year:'numeric'}).format(new Date(date + 'T00:00:00')); }
function money(value) { return '$' + Number(value || 0).toLocaleString(undefined,{minimumFractionDigits:2, maximumFractionDigits:2}); }
function initials(name) { return String(name||'?').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase(); }
function grade(mark) { return mark >= 80 ? 'A' : mark >= 70 ? 'B' : mark >= 60 ? 'C' : mark >= 50 ? 'D' : 'F'; }
function statusFor(fee) { return fee.paid >= fee.total ? ['Paid','green'] : fee.paid > 0 ? ['Partially Paid','yellow'] : ['Unpaid','red']; }
function pageTitle() { return ({dashboard:'Dashboard',students:'Students',teachers:'Teachers',classes:'Classes',subjects:'Subjects',attendance:'Attendance',results:'Exams & Results',fees:'Fees',timetable:'Timetable',announcements:'Announcements',reports:'Reports',settings:'Settings',pendingAccounts:'Pending Accounts',assignments:'Assignments',onlineExams:'Online Exams',analytics:'Performance Analytics',auditLog:'Activity Log',studentDashboard:'My Dashboard',studentProfile:'My Profile',studentResults:'My Results',studentAttendance:'My Attendance',studentAssignments:'Assignments',studentExams:'Exams',studentTimetable:'Timetable',studentFees:'Fees',studentAnnouncements:'Announcements',studentNotifications:'Notifications',pendingAccount:'Account Verification'})[page] || 'Dashboard'; }
const nav = [{key:'dashboard',label:'Dashboard',icon:'▦',file:'index.html'},{key:'students',label:'Students',icon:'◉',file:'students.html',roles:['Admin']},{key:'teachers',label:'Teachers',icon:'♙',file:'teachers.html',roles:['Admin']},{key:'classes',label:'Classes',icon:'▤',file:'classes.html',roles:['Admin']},{key:'subjects',label:'Subjects',icon:'◇',file:'subjects.html',roles:['Admin']},{key:'attendance',label:'Attendance',icon:'✓',file:'attendance.html',roles:['Admin','Teacher']},{key:'results',label:'Exams & Results',icon:'⌁',file:'results.html',roles:['Admin','Teacher']},{key:'assignments',label:'Assignments',icon:'A',file:'assignments.html',roles:['Admin','Teacher','Student','Parent']},{key:'onlineExams',label:'Online Exams',icon:'E',file:'online-exams.html',roles:['Admin','Teacher','Student']},{key:'analytics',label:'Performance',icon:'P',file:'analytics.html',roles:['Admin','Teacher','Student','Parent']},{key:'timetable',label:'Timetable',icon:'◫',file:'timetable.html',roles:['Admin']},{key:'announcements',label:'Announcements',icon:'!',file:'announcements.html',roles:['Admin']},{key:'fees',label:'Fees',icon:'$',file:'fees.html',roles:['Admin']},{key:'reports',label:'Reports',icon:'▥',file:'reports.html',roles:['Admin']},{key:'auditLog',label:'Activity Log',icon:'L',file:'activity-log.html',roles:['Admin']},{key:'pendingAccounts',label:'Pending Accounts',icon:'P',file:'pending-accounts.html',roles:['Admin']},{key:'settings',label:'Settings',icon:'⚙',file:'settings.html',roles:['Admin']}];
const studentNav = [{key:'studentDashboard',label:'Dashboard',icon:'▦',file:'student-dashboard.html'},{key:'studentProfile',label:'My Profile',icon:'◉',file:'student-profile.html'},{key:'studentResults',label:'My Results',icon:'R',file:'student-results.html'},{key:'studentAttendance',label:'My Attendance',icon:'✓',file:'student-attendance.html'},{key:'studentAssignments',label:'Assignments',icon:'A',file:'student-assignments.html'},{key:'studentExams',label:'Exams',icon:'E',file:'student-exams.html'},{key:'studentTimetable',label:'Timetable',icon:'◫',file:'student-timetable.html'},{key:'studentFees',label:'Fees',icon:'$',file:'student-fees.html'},{key:'studentAnnouncements',label:'Announcements',icon:'!',file:'student-announcements.html'},{key:'studentNotifications',label:'Notifications',icon:'N',file:'student-notifications.html'}];
function canAccess(key) { if(isRole('Student'))return key==='pendingAccount'||studentNav.some(entry=>entry.key===key); if(studentNav.some(entry=>entry.key===key))return false; const item=nav.find(entry=>entry.key===key); return !item || !item.roles || item.roles.includes(currentUser()?.role); }
function accessDenied() { return heading('Access restricted','Your role does not have access to this section.')+card('Role-based access','Please sign in with a role that has permission to use this area.'); }
function shell(content) { const s=db.settings, user=currentUser(); const logo=s.logo || 'assets/tayo-academy-logo.jpeg'; const menu=isRole('Student')?studentNav:nav.filter(item=>canAccess(item.key)); const unread=isRole('Student')?studentNotifications().filter(item=>!item.read&&!item.cleared).length:0; document.documentElement.dataset.theme=s.theme || 'light'; document.title='SchoolOS | '+pageTitle(); $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><img class="brand-mark" src="${esc(logo)}" alt="${esc(s.schoolName || 'TAYO ACADEMY')} logo"><div><strong>${esc(s.schoolName || 'TAYO ACADEMY')}</strong><small>${isRole('Student')?'Student Portal':'School operations'}</small></div></div><div class="nav-label">${isRole('Student')?'My learning':'Workspace'}</div><nav class="nav">${menu.map(item=>`<a class="${page===item.key?'active':''}" href="${item.file}"><span class="nav-icon">${item.icon}</span><span>${item.label}${item.key==='studentNotifications'&&unread?` <b class="nav-count">${unread}</b>`:''}</span></a>`).join('')}</nav><div class="sidebar-foot"><strong>${esc(user?.name||'Guest')}</strong><br><span>${esc(user?.role||'')}</span><button class="sidebar-logout" data-action="logout">Sign out</button></div></aside><main class="main"><header class="topbar"><div><h1>${pageTitle()}</h1><p>${formatDate(today())} · ${esc(s.schoolName || 'TAYO ACADEMY')}</p></div><div class="top-actions"><span class="school-pill">${esc(user?.role||'')}</span><button class="icon-button" id="themeToggle" title="Toggle theme">${s.theme==='dark'?'☀':'◐'}</button><div class="avatar">${initials(user?.name||'AD')}</div></div></header><section class="content">${content}</section></main></div><div id="modalRoot"></div>`; $('#themeToggle').onclick=toggleTheme; }
function toggleTheme() { db.settings.theme=db.settings.theme==='dark'?'light':'dark'; save('settings'); shell(renderPage()); bindPage(); }
function heading(title, subtitle, action='') { return `<div class="page-heading"><div><h2>${title}</h2><p>${subtitle}</p></div><div class="actions">${action}</div></div>`; }
function empty(title='No records yet', text='Add your first record to get started.') { return `<div class="empty"><strong>${title}</strong><span>${text}</span></div>`; }
function card(title, body, action='') { return `<div class="panel"><div class="panel-header"><h3>${title}</h3>${action}</div><div class="panel-body">${body}</div></div>`; }
let examTimer;
function refreshPage() { shell(renderPage()); bindPage(); }
function studentForCurrentUser() { const id=currentUser()?.studentId; return id?get('students',id):null; }
function assignmentSubmission(assignmentId,studentId) { return db.submissions.find(item=>item.assignmentId===assignmentId&&item.studentId===studentId); }
function studentAvatar(student,large=false) { if(student?.photo)return `<img class="student-photo ${large?'student-photo-lg':''}" src="${esc(student.photo)}" alt="${esc(student.name)}">`; return `<div class="profile-photo ${large?'student-photo-lg':''}">${initials(student?.name)}</div>`; }
function studentResults(studentId) { return db.results.filter(result=>result.studentId===studentId).slice().sort((a,b)=>b.date.localeCompare(a.date)); }
function studentAttendance(studentId) { return db.attendance.flatMap(entry=>Object.entries(entry.records).filter(([id])=>id===studentId).map(([,status])=>({date:entry.date,status,classId:entry.classId}))).sort((a,b)=>b.date.localeCompare(a.date)); }
function studentAssignments(student) { return db.assignments.filter(assignment=>assignment.classId===student.classId).slice().sort((a,b)=>a.dueDate.localeCompare(b.dueDate)); }
function studentExams(student) { return db.onlineExams.filter(exam=>exam.classId===student.classId).slice().sort((a,b)=>(a.scheduledDate||a.createdAt.slice(0,10)).localeCompare(b.scheduledDate||b.createdAt.slice(0,10))); }
function assignmentStatus(assignment,studentId) { const submission=assignmentSubmission(assignment.id,studentId); if(submission)return ['Submitted','green']; if(assignment.dueDate<today())return ['Late','red']; return ['Pending','yellow']; }
function studentNotifications() { const student=studentForCurrentUser(); if(!student)return []; const sources=[]; studentAssignments(student).filter(item=>!assignmentSubmission(item.id,student.id)).forEach(item=>sources.push({sourceId:'assignment-'+item.id,type:'Assignment',title:'New assignment: '+item.title,body:`${subjectName(item.subjectId)} is due ${formatDate(item.dueDate)}.`})); studentResults(student.id).forEach(item=>sources.push({sourceId:'result-'+item.id,type:'Result',title:'New result: '+subjectName(item.subjectId),body:`${item.exam}: ${item.marks}/${item.maxMarks} (${grade(item.marks)}).`})); studentExams(student).filter(item=>!db.examAttempts.some(attempt=>attempt.examId===item.id&&attempt.studentId===student.id)).forEach(item=>sources.push({sourceId:'exam-'+item.id,type:'Exam',title:'Upcoming exam: '+item.title,body:`${subjectName(item.subjectId)} · ${formatDate(item.scheduledDate||item.createdAt.slice(0,10))}.`})); db.announcements.filter(item=>!item.classId||item.classId===student.classId).forEach(item=>sources.push({sourceId:'announcement-'+item.id,type:'Announcement',title:item.title,body:item.message})); const fee=db.fees.find(item=>item.studentId===student.id);if(fee&&fee.paid<fee.total)sources.push({sourceId:'fee-'+fee.id,type:'Fees',title:'Fee balance reminder',body:`Your remaining balance is ${money(fee.total-fee.paid)}.`}); if(attendanceRate(student.id)<80&&studentAttendance(student.id).length)sources.push({sourceId:'attendance-'+student.id,type:'Attendance',title:'Attendance reminder',body:`Your current attendance is ${attendanceRate(student.id)}%.`}); let changed=false;sources.forEach(source=>{let item=db.notifications.find(notification=>notification.studentId===student.id&&notification.sourceId===source.sourceId);if(!item){item={id:uid('note'),studentId:student.id,sourceId:source.sourceId,...source,read:false,cleared:false,date:new Date().toISOString()};db.notifications.unshift(item);changed=true;}});if(changed)save('notifications');return db.notifications.filter(item=>item.studentId===student.id); }
function studentDashboardPage() { const student=studentForCurrentUser(); if(!student)return accessDenied(); const results=studentResults(student.id),attendance=studentAttendance(student.id),assignments=studentAssignments(student),exams=studentExams(student),fee=db.fees.find(item=>item.studentId===student.id),announcements=db.announcements.filter(item=>!item.classId||item.classId===student.classId).slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3),pending=assignments.filter(item=>!assignmentSubmission(item.id,student.id)&&item.dueDate>=today()); const latest=results.slice(0,4);return heading(`Welcome back, ${student.name.split(' ')[0]}`,'Your academic information is up to date.')+`<div class="student-summary">${studentAvatar(student,true)}<div><h3>${esc(student.name)}</h3><span>${esc(student.studentId)} · ${esc(className(student.classId))}</span><p>Academic year 2026</p></div></div><div class="stats-grid"><div class="stat-card"><div class="stat-top">Attendance</div><div class="stat-value">${attendanceRate(student.id)}%</div></div><div class="stat-card"><div class="stat-top">Current average</div><div class="stat-value">${performanceFor(student.id)}%</div></div><div class="stat-card"><div class="stat-top">Pending assignments</div><div class="stat-value">${pending.length}</div></div><div class="stat-card"><div class="stat-top">Fee balance</div><div class="stat-value">${money(fee?fee.total-fee.paid:0)}</div></div></div><div class="grid-2">${card('Latest results',latest.map(item=>`<div class="activity"><i class="activity-dot"></i><div><strong>${esc(subjectName(item.subjectId))} · ${item.marks}/${item.maxMarks}</strong><span>${esc(item.exam)} · Grade ${grade(item.marks)}</span></div></div>`).join('')||empty('No results yet'))}${card('Upcoming work',pending.slice(0,4).map(item=>`<div class="activity"><i class="activity-dot"></i><div><strong>${esc(item.title)}</strong><span>${esc(subjectName(item.subjectId))} · Due ${formatDate(item.dueDate)}</span></div></div>`).join('')||exams.slice(0,3).map(item=>`<div class="activity"><i class="activity-dot"></i><div><strong>${esc(item.title)}</strong><span>Exam · ${formatDate(item.scheduledDate||item.createdAt.slice(0,10))}</span></div></div>`).join('')||empty('No upcoming work'))}</div><br><div class="grid-2">${card('Today\'s timetable',db.timetable.filter(item=>item.classId===student.classId).slice(0,4).map(item=>`<div class="activity"><i class="activity-dot"></i><div><strong>${esc(item.day)} · ${esc(item.time)} · ${esc(subjectName(item.subjectId))}</strong><span>${esc(teacherName(item.teacherId))} · ${esc(className(student.classId))}</span></div></div>`).join('')||empty('No timetable entries'))}${card('Announcements',announcements.map(item=>`<div class="announcement-item"><strong>${esc(item.title)}</strong><p>${esc(item.message)}</p><span class="meta">${formatDate(item.date)}</span></div>`).join('')||empty('No announcements'))}</div>`; }
function studentProfilePage() { const student=studentForCurrentUser();if(!student)return accessDenied();return heading('My Profile','View your school profile and guardian information.')+`<div class="panel"><div class="panel-body"><div class="student-summary">${studentAvatar(student,true)}<div><h3>${esc(student.name)}</h3><span>${esc(student.studentId)} · ${esc(className(student.classId))}</span><p>Academic year 2026</p></div></div><div class="profile-grid"><div><span>Full name</span><strong>${esc(student.name)}</strong></div><div><span>Student ID</span><strong>${esc(student.studentId)}</strong></div><div><span>Class</span><strong>${esc(className(student.classId))}</strong></div><div><span>Date of birth</span><strong>${formatDate(student.dob)}</strong></div><div><span>Gender</span><strong>${esc(student.gender)}</strong></div><div><span>Phone</span><strong>${esc(student.phone)}</strong></div><div><span>Parent / guardian</span><strong>${esc(student.guardian)}</strong></div><div><span>Guardian phone</span><strong>${esc(student.parentPhone)}</strong></div><div class="profile-wide"><span>Address</span><strong>${esc(student.address)}</strong></div></div></div></div>`; }
function studentResultsPage() { const student=studentForCurrentUser(),results=student?studentResults(student.id):[];const averageScore=average(results.map(item=>item.marks));return heading('My Results','Review marks, grades, and overall performance.')+`<div class="kpi-row"><div class="kpi"><span>Overall average</span><strong>${averageScore}%</strong></div><div class="kpi"><span>Recorded exams</span><strong>${results.length}</strong></div><div class="kpi"><span>Performance</span><strong>${averageScore>=50?'Pass':'In progress'}</strong></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Subject</th><th>Exam</th><th>Marks</th><th>Grade</th><th>Status</th><th>Date</th></tr></thead><tbody>${results.map(item=>`<tr><td><strong>${esc(subjectName(item.subjectId))}</strong></td><td>${esc(item.exam)}</td><td>${item.marks}/${item.maxMarks}</td><td><span class="badge ${grade(item.marks)==='A'?'green':grade(item.marks)==='F'?'red':''}">${grade(item.marks)}</span></td><td><span class="badge ${item.marks>=50?'green':'red'}">${item.marks>=50?'Pass':'Fail'}</span></td><td>${formatDate(item.date)}</td></tr>`).join('')||`<tr><td colspan="6">${empty('No results recorded yet')}</td></tr>`}</tbody></table></div></div>`; }
function studentAttendancePage() { const student=studentForCurrentUser(),records=student?studentAttendance(student.id):[],present=records.filter(item=>item.status==='present').length,absent=records.filter(item=>item.status==='absent').length,late=records.filter(item=>item.status==='late').length;return heading('My Attendance','Review your attendance history. Attendance is managed by your teacher.')+`<div class="kpi-row"><div class="kpi"><span>Present</span><strong>${present}</strong></div><div class="kpi"><span>Absent</span><strong>${absent}</strong></div><div class="kpi"><span>Late</span><strong>${late}</strong></div><div class="kpi"><span>Attendance</span><strong>${student?attendanceRate(student.id):0}%</strong></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Date</th><th>Class</th><th>Status</th></tr></thead><tbody>${records.map(item=>`<tr><td>${formatDate(item.date)}</td><td>${esc(className(item.classId))}</td><td><span class="badge ${item.status==='present'?'green':item.status==='absent'?'red':'yellow'}">${esc(item.status)}</span></td></tr>`).join('')||`<tr><td colspan="3">${empty('No attendance records yet')}</td></tr>`}</tbody></table></div></div>`; }
function studentAssignmentsPage() { const student=studentForCurrentUser(),list=student?studentAssignments(student):[];return heading('Assignments','View class homework and submit your completed work.')+`<div class="panel"><div class="table-wrap"><table><thead><tr><th>Assignment</th><th>Subject</th><th>Teacher</th><th>Assigned</th><th>Due</th><th>Status</th><th>Action</th></tr></thead><tbody>${list.map(item=>{const status=assignmentStatus(item,student.id),teacher=get('users',item.createdBy)?.name||teacherName(get('subjects',item.subjectId)?.teacherId);return `<tr><td><strong>${esc(item.title)}</strong><div class="subtext">${esc(item.description)}</div></td><td>${esc(subjectName(item.subjectId))}</td><td>${esc(teacher)}</td><td>${formatDate(item.createdAt.slice(0,10))}</td><td>${formatDate(item.dueDate)}</td><td><span class="badge ${status[1]}">${status[0]}</span></td><td><button class="action-btn" data-action="submit-assignment" data-id="${item.id}" ${status[0]==='Submitted'?'disabled':''}>${status[0]==='Submitted'?'Submitted':'Submit'}</button></td></tr>`}).join('')||`<tr><td colspan="7">${empty('No assignments for your class')}</td></tr>`}</tbody></table></div></div>`; }
function studentExamsPage() { const student=studentForCurrentUser(),list=student?studentExams(student):[];return heading('My Exams','View upcoming assessments and complete available online exams.')+`<div class="panel"><div class="table-wrap"><table><thead><tr><th>Exam</th><th>Subject</th><th>Class</th><th>Date</th><th>Time / room</th><th>Status</th><th>Action</th></tr></thead><tbody>${list.map(item=>{const attempt=db.examAttempts.find(entry=>entry.examId===item.id&&entry.studentId===student.id),date=item.scheduledDate||item.createdAt.slice(0,10);return `<tr><td><strong>${esc(item.title)}</strong></td><td>${esc(subjectName(item.subjectId))}</td><td>${esc(className(item.classId))}</td><td>${formatDate(date)}</td><td>${esc(item.time||'To be announced')} · ${esc(item.room||className(item.classId))}</td><td>${attempt?`<span class="badge green">Completed · ${attempt.score}/${attempt.total}</span>`:`<span class="badge ${date<today()?'red':'yellow'}">${date<today()?'Past due':'Upcoming'}</span>`}</td><td>${attempt?'<span class="subtext">Score recorded</span>':`<button class="action-btn" data-action="take-exam" data-id="${item.id}">Start exam</button>`}</td></tr>`}).join('')||`<tr><td colspan="7">${empty('No exams for your class')}</td></tr>`}</tbody></table></div></div>`; }
function studentTimetablePage() { const student=studentForCurrentUser(),days=['Monday','Tuesday','Wednesday','Thursday','Friday'],list=student?db.timetable.filter(item=>item.classId===student.classId):[];return heading('My Timetable',student?`${className(student.classId)} schedule.`:'')+`<div class="timetable-grid">${days.map(day=>`<div class="day-column"><h4>${day}</h4>${list.filter(item=>item.day===day).sort((a,b)=>a.time.localeCompare(b.time)).map(item=>`<div class="slot"><strong>${esc(item.time)} · ${esc(subjectName(item.subjectId))}</strong><span>${esc(teacherName(item.teacherId))} · ${esc(className(student.classId))}</span><span>Room: ${esc(get('classes',student.classId)?.room||'-')} · Ends: ${esc(item.endTime||'To be confirmed')}</span></div>`).join('')||'<div class="empty">No classes</div>'}</div>`).join('')}</div>`; }
function studentFeesPage() { const student=studentForCurrentUser(),fees=student?db.fees.filter(item=>item.studentId===student.id):[],total=fees.reduce((sum,item)=>sum+item.total,0),paid=fees.reduce((sum,item)=>sum+item.paid,0);return heading('My Fees','View fee balances and payment history. Payments are managed by the school.')+`<div class="kpi-row"><div class="kpi"><span>Total fees</span><strong>${money(total)}</strong></div><div class="kpi"><span>Amount paid</span><strong>${money(paid)}</strong></div><div class="kpi"><span>Remaining balance</span><strong>${money(total-paid)}</strong></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Term</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th><th>Payment date</th><th>Note</th></tr></thead><tbody>${fees.map(item=>{const status=statusFor(item);return `<tr><td>${esc(item.term)}</td><td>${money(item.total)}</td><td>${money(item.paid)}</td><td>${money(item.total-item.paid)}</td><td><span class="badge ${status[1]}">${status[0]}</span></td><td>${formatDate(item.lastPayment)}</td><td>${esc(item.note||'-')}</td></tr>`}).join('')||`<tr><td colspan="7">${empty('No fee records yet')}</td></tr>`}</tbody></table></div></div>`; }
function studentAnnouncementsPage() { const student=studentForCurrentUser(),list=student?db.announcements.filter(item=>!item.classId||item.classId===student.classId).slice().sort((a,b)=>b.date.localeCompare(a.date)):[];return heading('Announcements','School and class updates for students.')+`<div class="grid-2">${list.map(item=>card(esc(item.title),`<p>${esc(item.message)}</p><span class="badge ${item.priority==='High'?'red':item.priority==='Important'?'yellow':''}">${esc(item.priority||'School-wide')}</span><p class="meta">${formatDate(item.date)}</p>`)).join('')||card('No announcements','There are no announcements for your class.')}</div>`; }
function studentNotificationsPage() { const list=studentNotifications().filter(item=>!item.cleared);return heading('Notifications','Stay informed about your school work and updates.',`<button class="btn btn-secondary" data-action="mark-all-notifications">Mark all read</button>`)+`<div class="panel"><div class="table-wrap"><table><thead><tr><th>Type</th><th>Notification</th><th>Date</th><th>Status</th><th>Action</th></tr></thead><tbody>${list.map(item=>`<tr class="${item.read?'':'notification-unread'}"><td><span class="badge">${esc(item.type)}</span></td><td><strong>${esc(item.title)}</strong><div class="subtext">${esc(item.body)}</div></td><td>${new Date(item.date).toLocaleString()}</td><td>${item.read?'Read':'Unread'}</td><td><div class="row-actions">${item.read?'':`<button class="action-btn" data-action="read-notification" data-id="${item.id}">Mark read</button>`}<button class="action-btn" data-action="clear-notification" data-id="${item.id}">Clear</button></div></td></tr>`).join('')||`<tr><td colspan="5">${empty('No notifications')}</td></tr>`}</tbody></table></div></div>`; }
function assignmentsPage() { const user=currentUser(), student=studentForCurrentUser(), canCreate=isRole('Admin','Teacher'); const list=student?db.assignments.filter(item=>item.classId===student.classId):db.assignments; return heading('Assignments','Create work, track due dates, and review submission status.',canCreate?'<button class="btn btn-primary" data-action="create-assignment">Add assignment</button>':'')+`<div class="panel"><div class="table-wrap"><table><thead><tr><th>Assignment</th><th>Class</th><th>Subject</th><th>Due date</th><th>${canCreate?'Submissions':'Status'}</th><th>Action</th></tr></thead><tbody>${list.map(item=>{const submission=student?assignmentSubmission(item.id,student.id):null;const submitted=db.submissions.filter(entry=>entry.assignmentId===item.id).length;return `<tr><td><strong>${esc(item.title)}</strong><div class="subtext">${esc(item.description)}</div></td><td>${esc(className(item.classId))}</td><td>${esc(subjectName(item.subjectId))}</td><td>${formatDate(item.dueDate)}</td><td>${canCreate?`${submitted}/${db.students.filter(s=>s.classId===item.classId).length} submitted`:`<span class="badge ${submission?'green':'yellow'}">${submission?'Submitted':'Pending'}</span>`}</td><td>${canCreate?`<button class="action-btn" data-action="view-submissions" data-id="${item.id}">View</button>`:isRole('Student')?`<button class="action-btn" data-action="submit-assignment" data-id="${item.id}" ${submission?'disabled':''}>${submission?'Submitted':'Submit'}</button>`:'<span class="subtext">Parent view</span>'}</td></tr>`}).join('')||`<tr><td colspan="6">${empty('No assignments yet','Assignments created for this class appear here.')}</td></tr>`}</tbody></table></div></div>`; }
function assignmentForm() { modal('Create assignment',`<form><p class="error"></p><div class="form-grid">${field('Assignment title','title')}${selectField('Class','classId',db.classes.map(item=>({value:item.id,label:item.name})))}${selectField('Subject','subjectId',db.subjects.map(item=>({value:item.id,label:item.name})))}${field('Due date','dueDate',today(),'date')}<div class="form-group full"><label>Instructions *</label><textarea name="description" required></textarea></div></div><div class="form-actions"><button type="button" class="btn btn-secondary" data-close-modal>Cancel</button><button class="btn btn-primary">Create assignment</button></div></form>`,fd=>{const value=Object.fromEntries(fd);value.id=uid('as');value.createdBy=currentUser().id;value.createdAt=new Date().toISOString();db.assignments.push(value);save('assignments');logActivity(`Created assignment ${value.title} for ${className(value.classId)}`);closeModal();showToast('Assignment created');refreshPage();}); }
function submissionForm(assignmentId) { const assignment=get('assignments',assignmentId), student=studentForCurrentUser(); if(!assignment||!student)return; const existing=assignmentSubmission(assignmentId,student.id); modal('Submit assignment',`<form><p class="error"></p><p class="subtext">${esc(assignment.title)} · Due ${formatDate(assignment.dueDate)}</p><div class="form-group"><label>Submission note *</label><textarea name="note" required>${esc(existing?.note||'Completed and ready for review.')}</textarea></div><div class="form-actions"><button type="button" class="btn btn-secondary" data-close-modal>Cancel</button><button class="btn btn-primary">Submit work</button></div></form>`,fd=>{const value=Object.fromEntries(fd);const item={id:existing?.id||uid('subm'),assignmentId,studentId:student.id,status:'Submitted',note:value.note,submittedAt:new Date().toISOString()};if(existing)Object.assign(existing,item);else db.submissions.push(item);save('submissions');logActivity(`Submitted assignment ${assignment.title}`);closeModal();showToast('Assignment submitted');refreshPage();}); }
function showSubmissions(assignmentId) { const assignment=get('assignments',assignmentId), entries=db.submissions.filter(item=>item.assignmentId===assignmentId); modal('Assignment submissions',`<p class="subtext">${esc(assignment?.title||'Assignment')}</p><div class="table-wrap"><table><thead><tr><th>Student</th><th>Status</th><th>Submitted</th><th>Note</th></tr></thead><tbody>${db.students.filter(student=>student.classId===assignment?.classId).map(student=>{const entry=entries.find(item=>item.studentId===student.id);return `<tr><td>${esc(student.name)}</td><td><span class="badge ${entry?'green':'yellow'}">${entry?.status||'Pending'}</span></td><td>${entry?new Date(entry.submittedAt).toLocaleString():'-'}</td><td>${esc(entry?.note||'-')}</td></tr>`}).join('')}</tbody></table></div><div class="form-actions"><button class="btn btn-secondary" data-close-modal>Close</button></div>`,()=>{}); }
function questionFields(index,question={}) { return `<div class="exam-question"><strong>Question ${index+1}</strong>${field('Question','question'+index,question.question||'')}<div class="form-grid">${[0,1,2,3].map(option=>field(`Option ${String.fromCharCode(65+option)}`,'option'+index+'_'+option,question.options?.[option]||'')).join('')}</div><div class="form-group"><label>Correct answer *</label><select name="answer${index}" required>${[0,1,2,3].map(option=>`<option value="${option}" ${Number(question.answer)===option?'selected':''}>Option ${String.fromCharCode(65+option)}</option>`).join('')}</select></div></div>`; }
function examForm() { modal('Create online exam',`<form><p class="error"></p><div class="form-grid">${field('Exam title','title')}${selectField('Class','classId',db.classes.map(item=>({value:item.id,label:item.name})))}${selectField('Subject','subjectId',db.subjects.map(item=>({value:item.id,label:item.name})))}${field('Time limit (minutes)','duration',10,'number',true,'min="1" max="120"')}${field('Exam date','scheduledDate',today(),'date')}${field('Start time','time','09:00','time')}${field('Room','room')}</div>${[0,1,2].map(index=>questionFields(index)).join('')}<div class="form-actions"><button type="button" class="btn btn-secondary" data-close-modal>Cancel</button><button class="btn btn-primary">Create exam</button></div></form>`,fd=>{const value=Object.fromEntries(fd);const questions=[0,1,2].map(index=>({question:value['question'+index],options:[0,1,2,3].map(option=>value['option'+index+'_'+option]),answer:Number(value['answer'+index])}));if(questions.some(item=>!item.question||item.options.some(option=>!option)))throw Error('Complete every question and answer option.');db.onlineExams.push({id:uid('ex'),title:value.title,classId:value.classId,subjectId:value.subjectId,duration:Number(value.duration),scheduledDate:value.scheduledDate,time:value.time,room:value.room,questions,createdBy:currentUser().id,createdAt:new Date().toISOString()});save('onlineExams');logActivity(`Created online exam ${value.title}`);closeModal();showToast('Online exam created');refreshPage();}); }
function onlineExamsPage() { const student=studentForCurrentUser(), canCreate=isRole('Admin','Teacher'); const list=student?db.onlineExams.filter(item=>item.classId===student.classId):db.onlineExams; return heading('Online Exams','Build multiple-choice assessments and automatically mark submissions.',canCreate?'<button class="btn btn-primary" data-action="create-exam">Create exam</button>':'')+`<div class="panel"><div class="table-wrap"><table><thead><tr><th>Exam</th><th>Class</th><th>Subject</th><th>Questions</th><th>Time</th><th>${canCreate?'Attempts':'Score'}</th><th>Action</th></tr></thead><tbody>${list.map(exam=>{const attempt=student?db.examAttempts.find(item=>item.examId===exam.id&&item.studentId===student.id):null;return `<tr><td><strong>${esc(exam.title)}</strong><div class="subtext">Created ${formatDate(exam.createdAt.slice(0,10))}</div></td><td>${esc(className(exam.classId))}</td><td>${esc(subjectName(exam.subjectId))}</td><td>${exam.questions.length}</td><td>${exam.duration} min</td><td>${canCreate?db.examAttempts.filter(item=>item.examId===exam.id).length:`${attempt?`${attempt.score}/${attempt.total}`:'Not attempted'}`}</td><td>${canCreate?'<span class="subtext">Automatic marking</span>':attempt?'<span class="badge green">Completed</span>':`<button class="action-btn" data-action="take-exam" data-id="${exam.id}">Start exam</button>`}</td></tr>`}).join('')||`<tr><td colspan="7">${empty('No online exams yet','Exams created for your class will appear here.')}</td></tr>`}</tbody></table></div></div>`; }
function takeExam(examId) { const exam=get('onlineExams',examId), student=studentForCurrentUser(); if(!exam||!student)return; let seconds=exam.duration*60; modal(exam.title,`<form id="examForm"><div class="exam-timer" id="examTimer">${exam.duration}:00</div><p class="subtext">${esc(subjectName(exam.subjectId))} · Answer all questions before the timer ends.</p>${exam.questions.map((item,index)=>`<fieldset class="exam-question"><legend>${index+1}. ${esc(item.question)}</legend>${item.options.map((option,optionIndex)=>`<label class="exam-option"><input type="radio" name="q${index}" value="${optionIndex}"> ${esc(option)}</label>`).join('')}</fieldset>`).join('')}<div class="form-actions"><button type="button" class="btn btn-secondary" data-close-modal>Cancel</button><button class="btn btn-primary">Submit exam</button></div></form>`,fd=>submitExam(exam,student,fd)); clearInterval(examTimer); examTimer=setInterval(()=>{seconds--;const display=$('#examTimer');if(display)display.textContent=`${Math.max(0,Math.floor(seconds/60))}:${String(Math.max(0,seconds%60)).padStart(2,'0')}`;if(seconds<=0){clearInterval(examTimer);$('#examForm')?.requestSubmit();}},1000); }
function submitExam(exam,student,fd) { clearInterval(examTimer); const score=exam.questions.reduce((total,question,index)=>total+(Number(fd.get('q'+index))===question.answer?1:0),0);db.examAttempts.push({id:uid('attempt'),examId:exam.id,studentId:student.id,score,total:exam.questions.length,submittedAt:new Date().toISOString()});save('examAttempts');logActivity(`Completed online exam ${exam.title} with ${score}/${exam.questions.length}`);closeModal();showToast(`Exam submitted: ${score}/${exam.questions.length}`);refreshPage(); }
function average(values) { return values.length?Math.round(values.reduce((sum,value)=>sum+value,0)/values.length):0; }
function attendanceRate(studentId) { const records=db.attendance.flatMap(item=>Object.entries(item.records).filter(([id])=>id===studentId).map(([,status])=>status)); return records.length?Math.round(records.filter(status=>status==='present').length/records.length*100):0; }
function performanceFor(studentId) { return average(db.results.filter(item=>item.studentId===studentId).map(item=>item.marks)); }
function analyticsPage() { const user=currentUser(), scoped=studentForCurrentUser(); const students=scoped?[scoped]:db.students; const classAverage=average(db.results.map(item=>item.marks)); const subjects=db.subjects.map(subject=>({name:subject.name,score:average(db.results.filter(item=>item.subjectId===subject.id).map(item=>item.marks))})).filter(item=>item.score||db.results.some(result=>subjectName(result.subjectId)===item.name)); const top=students.map(student=>({student,score:performanceFor(student.id),attendance:attendanceRate(student.id)})).sort((a,b)=>b.score-a.score).slice(0,5); return heading('Performance Analytics',scoped?`Performance overview for ${scoped.name}.`:'Review results, attendance, and class performance trends.')+`<div class="stats-grid"><div class="stat-card"><div class="stat-top">Class average</div><div class="stat-value">${classAverage}%</div></div><div class="stat-card"><div class="stat-top">Recorded results</div><div class="stat-value">${db.results.length}</div></div><div class="stat-card"><div class="stat-top">Top score</div><div class="stat-value">${top[0]?.score||0}%</div></div><div class="stat-card"><div class="stat-top">Average attendance</div><div class="stat-value">${average(students.map(student=>attendanceRate(student.id)))}%</div></div></div><div class="grid-2">${card('Subject performance',`<div class="bar-chart">${subjects.map(item=>`<div class="bar-row"><span>${esc(item.name)}</span><div class="progress"><i style="width:${item.score}%"></i></div><strong>${item.score}%</strong></div>`).join('')||'<div class="empty">No result data yet</div>'}`)}${card('Top-performing students',top.map(item=>`<div class="activity"><i class="activity-dot"></i><div><strong>${esc(item.student.name)} · ${item.score}%</strong><span>${esc(className(item.student.classId))} · ${item.attendance}% attendance</span></div></div>`).join('')||empty())}</div><br>${card('Attendance vs performance',`<div class="table-wrap"><table><thead><tr><th>Student</th><th>Class</th><th>Attendance</th><th>Average result</th><th>Trend</th></tr></thead><tbody>${students.map(student=>{const score=performanceFor(student.id),attendance=attendanceRate(student.id);return `<tr><td>${esc(student.name)}</td><td>${esc(className(student.classId))}</td><td>${attendance}%</td><td>${score}%</td><td><div class="progress"><i style="width:${score}%"></i></div></td></tr>`}).join('')}</tbody></table></div>`)} `; }
function auditLogPage() { return heading('Activity Log','Review the record of important actions across the school.')+`<div class="toolbar"><div class="search"><span>⌕</span><input id="auditSearch" placeholder="Search actions or people..."></div><select id="auditRoleFilter"><option value="">All roles</option><option>Admin</option><option>Teacher</option><option>Student</option><option>Parent</option><option>System</option></select></div><div class="panel"><div class="table-wrap"><table id="auditTable"><thead><tr><th>Date and time</th><th>Actor</th><th>Role</th><th>Action</th></tr></thead><tbody>${db.auditLogs.map(item=>`<tr data-search="${esc((item.actor+' '+item.action).toLowerCase())}" data-role="${esc(item.role)}"><td>${new Date(item.date).toLocaleString()}</td><td><strong>${esc(item.actor)}</strong></td><td><span class="badge">${esc(item.role)}</span></td><td>${esc(item.action)}</td></tr>`).join('')||`<tr><td colspan="4">${empty('No activity logged yet')}</td></tr>`}</tbody></table></div></div>`; }
function loginPage() { const logo=db.settings.logo||'assets/tayo-academy-logo.jpeg'; document.title='TAYO ACADEMY | Sign in'; $('#app').innerHTML=`<main class="login-page"><section class="login-panel"><img src="${esc(logo)}" alt="TAYO ACADEMY logo" class="login-logo"><h1>TAYO ACADEMY</h1><p>School Management System</p><form id="loginForm"><p class="error"></p>${field('Username, email, or student ID','username','','text',true,'autocomplete="username"')}${field('Password','password','','password',true,'autocomplete="current-password"')}<button class="btn btn-primary login-submit">Sign in</button></form><button class="login-link" id="showRegister" type="button">Create Student Account</button><div class="login-help"><strong>Demo accounts</strong><span>Admin: admin · Teacher: teacher · Password: tayo123</span><span>Students: ayaan.std, maxamed.std, hodan.std</span><span>Student password: student123</span></div></section></main>`; $('#loginForm').onsubmit=signIn; $('#showRegister').onclick=registrationPage; }
function registrationPage() { const logo=db.settings.logo||'assets/tayo-academy-logo.jpeg'; document.title='TAYO ACADEMY | Create Student Account'; $('#app').innerHTML=`<main class="login-page"><section class="login-panel registration-panel"><img src="${esc(logo)}" alt="TAYO ACADEMY logo" class="login-logo"><h1>Create Student Account</h1><p>Register to access your TAYO ACADEMY student portal.</p><form id="registrationForm"><p class="error"></p><p class="success"></p><div class="form-grid">${field('Full name','name')}${field('Student ID','studentId')}${field('Email','email','','email')}${field('Phone number','phone','','tel',true,'pattern="[0-9+() .-]{7,}"')}${selectField('Class','classId',db.classes.map(item=>({value:item.id,label:item.name})))}${field('Date of birth','dob','','date')}${selectField('Gender','gender',[{value:'Female',label:'Female'},{value:'Male',label:'Male'},{value:'Other',label:'Other'}])}</div><div class="password-field">${field('Password','password','','password',true,'minlength="6" autocomplete="new-password"')}<button class="password-toggle" type="button" data-password-toggle="password">Show</button></div><div class="password-field">${field('Confirm password','confirmPassword','','password',true,'minlength="6" autocomplete="new-password"')}<button class="password-toggle" type="button" data-password-toggle="confirmPassword">Show</button></div><button class="btn btn-primary login-submit">Create account</button></form><button class="login-link" id="showLogin" type="button">Back to sign in</button><p class="login-note">This is a local browser demo. It is not production-grade authentication.</p></section></main>`; $('#registrationForm').onsubmit=registerStudent; $('#showLogin').onclick=loginPage; $$('[data-password-toggle]').forEach(button=>button.onclick=()=>togglePassword(button.dataset.passwordToggle,button)); }
function togglePassword(name,button) { const input=document.querySelector(`[name="${name}"]`);if(!input)return;input.type=input.type==='password'?'text':'password';button.textContent=input.type==='password'?'Show':'Hide'; }
function registerStudent(event) { event.preventDefault(); const form=event.currentTarget,error=$('.error',form),success=$('.success',form),value=Object.fromEntries(new FormData(form));error.textContent='';success.textContent='';value.name=value.name.trim();value.studentId=value.studentId.trim();value.email=value.email.trim().toLowerCase(); if(!value.name||!value.studentId||!value.email||!value.phone||!value.classId||!value.dob||!value.gender||!value.password||!value.confirmPassword){error.textContent='Complete all required fields.';return;}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.email)){error.textContent='Enter a valid email address.';return;}if(value.password.length<6){error.textContent='Password must be at least 6 characters.';return;}if(value.password!==value.confirmPassword){error.textContent='Passwords do not match.';return;}if(db.users.some(user=>(user.email||'').toLowerCase()===value.email)){error.textContent='An account already uses this email address.';return;}const existingStudent=db.students.find(student=>student.studentId.toLowerCase()===value.studentId.toLowerCase());if(db.users.some(user=>(existingStudent&&user.studentId===existingStudent.id)||user.pendingStudentId?.toLowerCase()===value.studentId.toLowerCase())){error.textContent='An account already exists for this student ID.';return;}const account={id:uid('u'),name:value.name,username:value.email,password:value.password,email:value.email,phone:value.phone,role:'Student',status:existingStudent?'Approved':'Pending Verification',studentId:existingStudent?.id||'',pendingStudentId:existingStudent?'':value.studentId,pendingClassId:value.classId,dob:value.dob,gender:value.gender,registeredAt:new Date().toISOString()};db.users.push(account);save('users');logActivity(`Registered student account for ${value.name}`);success.textContent=existingStudent?'Account created and linked to your existing student record. You can now sign in.':'Your account has been created. Please wait for school administration to verify your account.';form.reset(); }
function signIn(event) { event.preventDefault(); const form=event.currentTarget, value=Object.fromEntries(new FormData(form)), identifier=value.username.trim().toLowerCase(), user=db.users.find(item=>(item.username.toLowerCase()===identifier||(item.email||'').toLowerCase()===identifier||((item.studentNumber||get('students',item.studentId)?.studentId||'').toLowerCase()===identifier))&&item.password===value.password); if(!user){$('.error',form).textContent='Incorrect username, email, student ID, or password.';return;}if(user.status==='Rejected'){$('.error',form).textContent='This registration was not approved. Please contact school administration.';return;} sessionStorage.setItem('schoolos_session',JSON.stringify({id:user.id,name:user.name,role:user.role,studentId:user.studentId||'',teacherId:user.teacherId||'',status:user.status||'Approved'})); logActivity('Signed in'); if(user.role==='Student'){location.href=(user.status||'Approved')==='Approved'?'student-dashboard.html':'pending-account.html';return;}location.href='index.html'; }
function pendingAccountPage() { const user=currentUser();return heading('Account Verification','Your student account is awaiting school approval.')+card('Registration received',`<p>Your account for <strong>${esc(user?.name||'student')}</strong> has been created. Please wait for school administration to verify your student information before accessing academic records.</p><p class="subtext">Student ID: ${esc(get('users',user?.id)?.pendingStudentId||get('students',user?.studentId)?.studentId||'-')}</p>`, '<button class="btn btn-secondary btn-sm" data-action="logout">Sign out</button>'); }
function pendingAccountsPage() { const accounts=db.users.filter(user=>user.role==='Student'&&user.status==='Pending Verification');return heading('Pending Student Accounts','Review and verify new student registrations.')+`<div class="panel"><div class="table-wrap"><table><thead><tr><th>Student</th><th>Student ID</th><th>Class</th><th>Contact</th><th>Registered</th><th>Actions</th></tr></thead><tbody>${accounts.map(account=>`<tr><td><strong>${esc(account.name)}</strong><div class="subtext">${esc(account.email)}</div></td><td>${esc(account.pendingStudentId||get('students',account.studentId)?.studentId||'-')}</td><td>${esc(className(account.pendingClassId||get('students',account.studentId)?.classId))}</td><td>${esc(account.phone||'-')}</td><td>${new Date(account.registeredAt).toLocaleString()}</td><td><div class="row-actions"><button class="action-btn" data-action="view-pending-account" data-id="${account.id}">View</button><button class="action-btn" data-action="approve-account" data-id="${account.id}">Approve</button><button class="action-btn" data-action="reject-account" data-id="${account.id}">Reject</button></div></td></tr>`).join('')||`<tr><td colspan="6">${empty('No pending student accounts')}</td></tr>`}</tbody></table></div></div>`; }
function viewPendingAccount(id) { const account=get('users',id);if(!account)return;modal('Student registration',`<div class="profile-grid"><div><span>Full name</span><strong>${esc(account.name)}</strong></div><div><span>Student ID</span><strong>${esc(account.pendingStudentId||get('students',account.studentId)?.studentId||'-')}</strong></div><div><span>Email</span><strong>${esc(account.email)}</strong></div><div><span>Phone</span><strong>${esc(account.phone||'-')}</strong></div><div><span>Requested class</span><strong>${esc(className(account.pendingClassId))}</strong></div><div><span>Date of birth</span><strong>${formatDate(account.dob)}</strong></div><div><span>Gender</span><strong>${esc(account.gender||'-')}</strong></div><div><span>Status</span><strong>${esc(account.status||'Approved')}</strong></div></div><div class="form-actions"><button class="btn btn-secondary" data-close-modal>Close</button></div>`,()=>{}); }
function approveStudentAccount(id) { const account=get('users',id);if(!account||account.role!=='Student'||account.status!=='Pending Verification')return;let student=db.students.find(item=>item.studentId.toLowerCase()===(account.pendingStudentId||'').toLowerCase());if(!student){student={id:uid('s'),name:account.name,studentId:account.pendingStudentId,gender:account.gender,dob:account.dob,classId:account.pendingClassId,phone:account.phone,guardian:'Pending guardian details',parentPhone:'-',address:'Pending school verification'};db.students.push(student);save('students');}account.studentId=student.id;account.status='Approved';delete account.pendingStudentId;delete account.pendingClassId;save('users');logActivity(`Approved student account for ${account.name}`);showToast('Student account approved');refreshPage(); }
function rejectStudentAccount(id) { const account=get('users',id);if(!account||account.role!=='Student'||account.status!=='Pending Verification')return;if(!confirm(`Reject the registration for ${account.name}?`))return;account.status='Rejected';save('users');logActivity(`Rejected student account for ${account.name}`);showToast('Student account rejected');refreshPage(); }
function signOut() { sessionStorage.removeItem('schoolos_session'); location.href='login.html'; }
function dashboard() { const user=currentUser(); const present=Object.values(db.attendance.reduce((a,x)=>({...a,...x.records}),{})).filter(x=>x==='present').length; const absent=Object.values(db.attendance.reduce((a,x)=>({...a,...x.records}),{})).filter(x=>x==='absent').length; const paid=db.fees.reduce((a,x)=>a+x.paid,0), unpaid=db.fees.reduce((a,x)=>a+Math.max(x.total-x.paid,0),0); return heading(`Good morning, ${user?.name||'Administrator'}`,'Here is what is happening across your school today.')+`<div class="stats-grid"><div class="stat-card" style="--stat-color:#1363df"><div class="stat-top">Total Students <span class="stat-icon">◉</span></div><div class="stat-value">${db.students.length}</div></div><div class="stat-card" style="--stat-color:#19a974"><div class="stat-top">Total Teachers <span class="stat-icon">♙</span></div><div class="stat-value">${db.teachers.length}</div></div><div class="stat-card" style="--stat-color:#f59e0b"><div class="stat-top">Total Classes <span class="stat-icon">▤</span></div><div class="stat-value">${db.classes.length}</div></div><div class="stat-card" style="--stat-color:#8b5cf6"><div class="stat-top">Total Subjects <span class="stat-icon">◇</span></div><div class="stat-value">${db.subjects.length}</div></div><div class="stat-card" style="--stat-color:#19a974"><div class="stat-top">Present Students <span class="stat-icon">✓</span></div><div class="stat-value">${present}</div></div><div class="stat-card" style="--stat-color:#e05252"><div class="stat-top">Absent Students <span class="stat-icon">×</span></div><div class="stat-value">${absent}</div></div><div class="stat-card" style="--stat-color:#1363df"><div class="stat-top">Paid Fees <span class="stat-icon">$</span></div><div class="stat-value">${money(paid)}</div></div><div class="stat-card" style="--stat-color:#f59e0b"><div class="stat-top">Unpaid Fees <span class="stat-icon">!</span></div><div class="stat-value">${money(unpaid)}</div></div></div><div class="grid-2">${card('Recent activity',db.activities.slice(0,5).map(x=>`<div class="activity"><i class="activity-dot"></i><div><strong>${esc(x.text)}</strong><span>${new Date(x.date).toLocaleString()}</span></div></div>`).join('')||empty())}${card('Recent announcements',db.announcements.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4).map(x=>`<div class="announcement-item"><strong>${esc(x.title)}</strong><p>${esc(x.message)}</p><span class="meta">${formatDate(x.date)}</span></div>`).join('')||empty(),' <a class="btn btn-secondary btn-sm" href="announcements.html">View all</a>')}</div>`; }
function modal(title, body, onSubmit) { $('#modalRoot').innerHTML=`<div class="modal-backdrop" data-close-modal><div class="modal"><div class="modal-header"><h3>${title}</h3><button class="close" data-close-modal>×</button></div><div class="modal-body">${body}</div></div></div>`; const form=$('form', $('#modalRoot')); if(form) form.onsubmit=e=>{e.preventDefault(); const error=$('.error',form); if(error) error.textContent=''; try { onSubmit(new FormData(form),form); } catch(err) { if(error) error.textContent=err.message; } }; $$('[data-close-modal]', $('#modalRoot')).forEach(x=>x.onclick=closeModal); $$('.modal-backdrop').forEach(x=>x.onclick=e=>{if(e.target===x) x.remove()}); }
function field(label,name,value='',type='text',required=true,extra='') { return `<div class="form-group"><label>${label}${required?' *':''}</label><input type="${type}" name="${name}" value="${esc(value)}" ${required?'required':''} ${extra}></div>`; }
function selectField(label,name,options,value='',required=true) { return `<div class="form-group"><label>${label}${required?' *':''}</label><select name="${name}" ${required?'required':''}><option value="">Select ${label.toLowerCase()}</option>${options.map(o=>`<option value="${o.value}" ${o.value===value?'selected':''}>${esc(o.label)}</option>`).join('')}</select></div>`; }
function formModal(title, fields, submit, initial={}) { modal(title,`<form><p class="error"></p><div class="form-grid">${fields(initial)}</div><div class="form-actions"><button type="button" class="btn btn-secondary" data-close-modal>Cancel</button><button class="btn btn-primary">${submit}</button></div></form>`,()=>{}); }
function closeModal() { clearInterval(examTimer); const x=$('.modal-backdrop'); if(x)x.remove(); }
function addRecord(key, value, message) { db[key].push(value); save(key); logActivity(message); closeModal(); showToast(message); shell(renderPage()); bindPage(); }
function editRecord(key,id,value,message) { const index=db[key].findIndex(x=>x.id===id); db[key][index]={...db[key][index],...value}; save(key); logActivity(message); closeModal(); showToast(message); shell(renderPage()); bindPage(); }
function removeRecord(key,id,label) { if(!confirm(`Delete ${label}? This cannot be undone.`))return; db[key]=db[key].filter(x=>x.id!==id); save(key); logActivity(`Deleted ${label}`); showToast('Record deleted'); shell(renderPage()); bindPage(); }
function studentForm(record={}) { const fields=i=>field('Full name','name',i.name)+field('Student ID','studentId',i.studentId)+selectField('Gender','gender',[{value:'Female',label:'Female'},{value:'Male',label:'Male'},{value:'Other',label:'Other'}],i.gender)+field('Date of birth','dob',i.dob,'date')+selectField('Class','classId',db.classes.map(x=>({value:x.id,label:x.name})),i.classId)+field('Phone','phone',i.phone,'tel',true,'pattern="[0-9+() .-]{7,}"')+field('Parent/Guardian','guardian',i.guardian)+field('Parent phone','parentPhone',i.parentPhone,'tel',true,'pattern="[0-9+() .-]{7,}"')+`<div class="form-group full"><label>Address *</label><textarea name="address" required>${esc(i.address)}</textarea></div>`; modal(record.id?'Edit student':'Add student',`<form><p class="error"></p><div class="form-grid">${fields(record)}</div><div class="form-actions"><button type="button" class="btn btn-secondary" data-close-modal>Cancel</button><button class="btn btn-primary">Save student</button></div></form>`,fd=>{const value=Object.fromEntries(fd); if(db.students.some(x=>x.studentId.toLowerCase()===value.studentId.toLowerCase()&&x.id!==record.id))throw Error('Student ID must be unique.'); if(!record.id)value.id=uid('s'); record.id?editRecord('students',record.id,value,`Updated student ${value.name}`):addRecord('students',value,`Added student ${value.name}`)}); }
function studentsPage(){ return heading('Students','Manage enrollment, profiles, and guardians.', '<button class="btn btn-primary" data-action="add-student">＋ Add student</button>')+`<div class="toolbar"><div class="search"><span>⌕</span><input id="tableSearch" placeholder="Search by name or student ID..."></div><div class="filters"><select id="classFilter"><option value="">All classes</option>${db.classes.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><select id="genderFilter"><option value="">All genders</option><option value="Female">Female</option><option value="Male">Male</option></select></div></div><div class="panel"><div class="table-wrap"><table id="dataTable"><thead><tr><th>Student</th><th>ID</th><th>Age</th><th>Class</th><th>Gender</th><th>Contact</th><th>Actions</th></tr></thead><tbody>${db.students.map(s=>`<tr data-search="${esc((s.name+' '+s.studentId).toLowerCase())}" data-class="${s.classId}" data-gender="${s.gender}"><td><div class="person"><div class="avatar">${initials(s.name)}</div><div><strong>${esc(s.name)}</strong><div class="subtext">${esc(s.guardian)}</div></div></div></td><td>${esc(s.studentId)}</td><td>${ageFromDob(s.dob)}</td><td><span class="badge">${esc(className(s.classId))}</span></td><td>${esc(s.gender)}</td><td>${esc(s.phone)}</td><td><div class="row-actions"><button class="action-btn" data-action="view-student" data-id="${s.id}">View</button><button class="action-btn" data-action="edit-student" data-id="${s.id}">Edit</button><button class="action-btn" data-action="delete-student" data-id="${s.id}">Delete</button></div></td></tr>`).join('')||`<tr><td colspan="7">${empty()}</td></tr>`}</tbody></table></div></div>`; }
function teacherForm(record={}) { const fields=i=>field('Full name','name',i.name)+field('Teacher ID','teacherId',i.teacherId)+selectField('Gender','gender',[{value:'Female',label:'Female'},{value:'Male',label:'Male'}],i.gender)+selectField('Subject','subjectId',db.subjects.map(x=>({value:x.id,label:x.name})),i.subjectId)+selectField('Class','classId',db.classes.map(x=>({value:x.id,label:x.name})),i.classId)+field('Phone','phone',i.phone,'tel',true,'pattern="[0-9+() .-]{7,}"')+field('Email','email',i.email,'email')+`<div class="form-group full"><label>Address *</label><textarea name="address" required>${esc(i.address)}</textarea></div>`; modal(record.id?'Edit teacher':'Add teacher',`<form><p class="error"></p><div class="form-grid">${fields(record)}</div><div class="form-actions"><button type="button" class="btn btn-secondary" data-close-modal>Cancel</button><button class="btn btn-primary">Save teacher</button></div></form>`,fd=>{const value=Object.fromEntries(fd);if(db.teachers.some(x=>x.teacherId.toLowerCase()===value.teacherId.toLowerCase()&&x.id!==record.id))throw Error('Teacher ID must be unique.');if(!record.id)value.id=uid('t');record.id?editRecord('teachers',record.id,value,`Updated teacher ${value.name}`):addRecord('teachers',value,`Added teacher ${value.name}`)}); }
function teachersPage(){return heading('Teachers','Keep staff profiles and teaching assignments current.','<button class="btn btn-primary" data-action="add-teacher">＋ Add teacher</button>')+`<div class="toolbar"><div class="search"><span>⌕</span><input id="tableSearch" placeholder="Search teachers..."></div><div class="filters"><select id="teacherSubjectFilter"><option value="">All subjects</option>${db.subjects.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><select id="teacherClassFilter"><option value="">All classes</option>${db.classes.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div></div><div class="panel"><div class="table-wrap"><table id="dataTable"><thead><tr><th>Teacher</th><th>ID</th><th>Subject</th><th>Class</th><th>Contact</th><th>Actions</th></tr></thead><tbody>${db.teachers.map(t=>`<tr data-search="${esc((t.name+' '+t.teacherId+' '+t.email).toLowerCase())}" data-subject="${t.subjectId}" data-class="${t.classId}"><td><div class="person"><div class="avatar">${initials(t.name)}</div><strong>${esc(t.name)}</strong></div></td><td>${esc(t.teacherId)}</td><td>${esc(subjectName(t.subjectId))}</td><td>${esc(className(t.classId))}</td><td>${esc(t.phone)}<div class="subtext">${esc(t.email)}</div></td><td><div class="row-actions"><button class="action-btn" data-action="view-teacher" data-id="${t.id}">View</button><button class="action-btn" data-action="edit-teacher" data-id="${t.id}">Edit</button><button class="action-btn" data-action="delete-teacher" data-id="${t.id}">Delete</button></div></td></tr>`).join('')||`<tr><td colspan="6">${empty()}</td></tr>`}</tbody></table></div></div>`; }
function classForm(record={}){modal(record.id?'Edit class':'Add class',`<form><p class="error"></p><div class="form-grid">${field('Class name','name',record.name)}${field('Section','section',record.section)}${field('Room','room',record.room)}${selectField('Class teacher','teacherId',db.teachers.map(x=>({value:x.id,label:x.name})),record.teacherId,false)}</div><div class="form-actions"><button type="button" class="btn btn-secondary" data-close-modal>Cancel</button><button class="btn btn-primary">Save class</button></div></form>`,fd=>{const value=Object.fromEntries(fd);if(!record.id)value.id=uid('c');record.id?editRecord('classes',record.id,value,`Updated class ${value.name}`):addRecord('classes',value,`Added class ${value.name}`)});}
function classesPage(){return heading('Classes','Organize rooms, sections, and class ownership.','<button class="btn btn-primary" data-action="add-class">＋ Add class</button>')+`<div class="toolbar"><div class="search"><span>⌕</span><input id="tableSearch" placeholder="Search classes..."></div></div><div class="panel"><div class="table-wrap"><table id="dataTable"><thead><tr><th>Class</th><th>Section</th><th>Room</th><th>Teacher</th><th>Students</th><th>Actions</th></tr></thead><tbody>${db.classes.map(c=>`<tr data-search="${esc((c.name+' '+c.section+' '+c.room).toLowerCase())}"><td><strong>${esc(c.name)}</strong></td><td>${esc(c.section)}</td><td>${esc(c.room)}</td><td>${esc(teacherName(c.teacherId))}</td><td><span class="badge">${db.students.filter(s=>s.classId===c.id).length} enrolled</span></td><td><div class="row-actions"><button class="action-btn" data-action="edit-class" data-id="${c.id}">Edit</button><button class="action-btn" data-action="delete-class" data-id="${c.id}">Delete</button></div></td></tr>`).join('')||`<tr><td colspan="6">${empty()}</td></tr>`}</tbody></table></div></div>`;}
function subjectForm(record={}){modal(record.id?'Edit subject':'Add subject',`<form><p class="error"></p><div class="form-grid">${field('Subject name','name',record.name)}${field('Subject code','code',record.code)}${selectField('Teacher','teacherId',db.teachers.map(x=>({value:x.id,label:x.name})),record.teacherId,false)}<div class="form-group"><label>Assigned classes</label><select name="classIds" multiple size="3">${db.classes.map(x=>`<option value="${x.id}" ${(record.classIds||[]).includes(x.id)?'selected':''}>${esc(x.name)}</option>`).join('')}</select><span class="subtext">Hold Ctrl to choose more than one</span></div></div><div class="form-actions"><button type="button" class="btn btn-secondary" data-close-modal>Cancel</button><button class="btn btn-primary">Save subject</button></div></form>`,fd=>{const value=Object.fromEntries(fd);value.classIds=fd.getAll('classIds');if(!record.id)value.id=uid('sub');record.id?editRecord('subjects',record.id,value,`Updated subject ${value.name}`):addRecord('subjects',value,`Added subject ${value.name}`)});}
function subjectsPage(){return heading('Subjects','Manage curriculum and teaching assignments.','<button class="btn btn-primary" data-action="add-subject">＋ Add subject</button>')+`<div class="toolbar"><div class="search"><span>⌕</span><input id="tableSearch" placeholder="Search subjects or codes..."></div></div><div class="panel"><div class="table-wrap"><table id="dataTable"><thead><tr><th>Subject</th><th>Code</th><th>Classes</th><th>Teacher</th><th>Actions</th></tr></thead><tbody>${db.subjects.map(s=>`<tr data-search="${esc((s.name+' '+s.code).toLowerCase())}"><td><strong>${esc(s.name)}</strong></td><td>${esc(s.code)}</td><td>${(s.classIds||[]).map(className).join(', ')||'None'}</td><td>${esc(teacherName(s.teacherId))}</td><td><div class="row-actions"><button class="action-btn" data-action="edit-subject" data-id="${s.id}">Edit</button><button class="action-btn" data-action="delete-subject" data-id="${s.id}">Delete</button></div></td></tr>`).join('')||`<tr><td colspan="5">${empty()}</td></tr>`}</tbody></table></div></div>`;}
function attendancePage(){const date=$('#attendanceDate')?.value||today(), classId=$('#attendanceClass')?.value||db.classes[0]?.id||'';const existing=db.attendance.find(x=>x.date===date&&x.classId===classId);const list=db.students.filter(s=>s.classId===classId);return heading('Attendance','Take daily attendance by class and review historical records.','<button class="btn btn-primary" data-action="save-attendance">✓ Save attendance</button>')+`<div class="toolbar"><div class="filters"><input type="date" id="attendanceDate" value="${date}"><select id="attendanceClass">${db.classes.map(x=>`<option value="${x.id}" ${x.id===classId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="meta">${existing?'Editing saved attendance':'New attendance sheet'}</div></div><div class="panel"><div class="panel-header"><h3>${esc(className(classId))} roster</h3><div class="actions"><button class="btn btn-secondary btn-sm" data-action="mark-all" data-status="present">Mark all present</button><button class="btn btn-secondary btn-sm" data-action="mark-all" data-status="absent">Mark all absent</button></div></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Status</th></tr></thead><tbody>${list.map(s=>{const status=existing?.records[s.id]||'present';return `<tr><td><div class="person"><div class="avatar">${initials(s.name)}</div><strong>${esc(s.name)}</strong></div></td><td><select class="attendance-status" data-student="${s.id}"><option value="present" ${status==='present'?'selected':''}>Present</option><option value="absent" ${status==='absent'?'selected':''}>Absent</option><option value="late" ${status==='late'?'selected':''}>Late</option></select></td></tr>`}).join('')||`<tr><td colspan="2">${empty('No students in this class','Add students before taking attendance.')}</td></tr>`}</tbody></table></div></div><br>${card('Previous attendance',db.attendance.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(a=>{const values=Object.values(a.records);return `<div class="activity"><i class="activity-dot"></i><div><strong>${formatDate(a.date)} · ${esc(className(a.classId))}</strong><span>${values.filter(x=>x==='present').length} present · ${values.filter(x=>x==='absent').length} absent · ${values.filter(x=>x==='late').length} late <button class="action-btn" data-action="load-attendance" data-date="${a.date}" data-class="${a.classId}">Edit</button></span></div></div>`}).join('')||empty())}`;}
function resultsPage(){return heading('Exams & Results','Record marks, grades, and student performance.','<button class="btn btn-primary" data-action="add-result">＋ Add result</button>')+`<div class="toolbar"><div class="search"><span>⌕</span><input id="tableSearch" placeholder="Search exam, student, or subject..."></div><select id="resultClassFilter"><option value="">All classes</option>${db.classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="panel"><div class="table-wrap"><table id="dataTable"><thead><tr><th>Exam</th><th>Student</th><th>Class</th><th>Subject</th><th>Marks</th><th>Grade</th><th>Actions</th></tr></thead><tbody>${db.results.map(r=>`<tr data-search="${esc((r.exam+' '+studentName(r.studentId)+' '+subjectName(r.subjectId)).toLowerCase())}" data-class="${r.classId}"><td><strong>${esc(r.exam)}</strong><div class="subtext">${formatDate(r.date)}</div></td><td>${esc(studentName(r.studentId))}</td><td>${esc(className(r.classId))}</td><td>${esc(subjectName(r.subjectId))}</td><td>${r.marks}/${r.maxMarks}</td><td><span class="badge ${grade(r.marks)==='F'?'red':grade(r.marks)==='A'?'green':''}">${grade(r.marks)}</span></td><td><div class="row-actions"><button class="action-btn" data-action="edit-result" data-id="${r.id}">Edit</button><button class="action-btn" data-action="delete-result" data-id="${r.id}">Delete</button></div></td></tr>`).join('')||`<tr><td colspan="7">${empty()}</td></tr>`}</tbody></table></div></div>`;}
function resultForm(record={}){modal(record.id?'Edit result':'Add result',`<form><p class="error"></p><div class="form-grid">${field('Exam name','exam',record.exam)}${field('Date','date',record.date||today(),'date')}${selectField('Class','classId',db.classes.map(x=>({value:x.id,label:x.name})),record.classId)}${selectField('Student','studentId',db.students.map(x=>({value:x.id,label:x.name+' · '+x.studentId})),record.studentId)}${selectField('Subject','subjectId',db.subjects.map(x=>({value:x.id,label:x.name})),record.subjectId)}${field('Marks','marks',record.marks,'number',true,'min="0" max="100" step="0.01"')}</div><div class="form-actions"><button type="button" class="btn btn-secondary" data-close-modal>Cancel</button><button class="btn btn-primary">Save result</button></div></form>`,fd=>{const value=Object.fromEntries(fd);value.marks=Number(value.marks);value.maxMarks=100;if(value.marks<0||value.marks>100)throw Error('Marks must be between 0 and 100.');if(!record.id)value.id=uid('r');record.id?editRecord('results',record.id,value,`Updated result for ${studentName(value.studentId)}`):addRecord('results',value,`Added result for ${studentName(value.studentId)}`)});}
function feeForm(record={}){modal(record.id?'Edit fee record':'Add fee record',`<form><p class="error"></p><div class="form-grid">${selectField('Student','studentId',db.students.map(x=>({value:x.id,label:x.name+' · '+x.studentId})),record.studentId)}${field('Term','term',record.term||'Fall 2026')}${field('Total fee','total',record.total,'number',true,'min="0" step="0.01"')}${field('Amount paid','paid',record.paid||0,'number',true,'min="0" step="0.01"')}${field('Last payment','lastPayment',record.lastPayment||today(),'date')}<div class="form-group full"><label>Note</label><textarea name="note">${esc(record.note)}</textarea></div></div><div class="form-actions"><button type="button" class="btn btn-secondary" data-close-modal>Cancel</button><button class="btn btn-primary">Save fee record</button></div></form>`,fd=>{const value=Object.fromEntries(fd);value.total=Number(value.total);value.paid=Number(value.paid);if(value.paid>value.total)throw Error('Paid fee cannot be greater than total fee.');if(value.total<0||value.paid<0)throw Error('Fee amounts cannot be negative.');if(!record.id)value.id=uid('f');record.id?editRecord('fees',record.id,value,`Updated fee record for ${studentName(value.studentId)}`):addRecord('fees',value,`Added fee record for ${studentName(value.studentId)}`)});}
function feesPage(){const total=db.fees.reduce((a,x)=>a+x.total,0),paid=db.fees.reduce((a,x)=>a+x.paid,0);return heading('Fees','Track invoices, payments, and outstanding balances.','<button class="btn btn-primary" data-action="add-fee">＋ Add fee record</button>')+`<div class="kpi-row"><div class="kpi"><span>Total billed</span><strong>${money(total)}</strong></div><div class="kpi"><span>Amount paid</span><strong>${money(paid)}</strong></div><div class="kpi"><span>Outstanding</span><strong>${money(total-paid)}</strong></div></div><div class="toolbar"><div class="search"><span>⌕</span><input id="tableSearch" placeholder="Search student or term..."></div><select id="feeFilter"><option value="">All statuses</option><option value="Paid">Paid</option><option value="Partially Paid">Partially Paid</option><option value="Unpaid">Unpaid</option></select></div><div class="panel"><div class="table-wrap"><table id="dataTable"><thead><tr><th>Student</th><th>Term</th><th>Total fee</th><th>Paid</th><th>Balance</th><th>Status</th><th>Actions</th></tr></thead><tbody>${db.fees.map(f=>{const st=statusFor(f);return `<tr data-search="${esc((studentName(f.studentId)+' '+f.term).toLowerCase())}" data-status="${st[0]}"><td><strong>${esc(studentName(f.studentId))}</strong></td><td>${esc(f.term)}</td><td>${money(f.total)}</td><td>${money(f.paid)}</td><td>${money(f.total-f.paid)}</td><td><span class="badge ${st[1]}">${st[0]}</span></td><td><div class="row-actions"><button class="action-btn" data-action="view-fee" data-id="${f.id}">History</button><button class="action-btn" data-action="edit-fee" data-id="${f.id}">Edit</button><button class="action-btn" data-action="delete-fee" data-id="${f.id}">Delete</button></div></td></tr>`}).join('')||`<tr><td colspan="7">${empty()}</td></tr>`}</tbody></table></div></div>`;}
function timetableForm(record={}){modal(record.id?'Edit timetable entry':'Add timetable entry',`<form><p class="error"></p><div class="form-grid">${selectField('Day','day',['Monday','Tuesday','Wednesday','Thursday','Friday'].map(x=>({value:x,label:x})),record.day)}${field('Start time','time',record.time,'time')}${field('End time','endTime',record.endTime,'time',false)}${selectField('Class','classId',db.classes.map(x=>({value:x.id,label:x.name})),record.classId)}${selectField('Subject','subjectId',db.subjects.map(x=>({value:x.id,label:x.name})),record.subjectId)}${selectField('Teacher','teacherId',db.teachers.map(x=>({value:x.id,label:x.name})),record.teacherId,false)}</div><div class="form-actions"><button type="button" class="btn btn-secondary" data-close-modal>Cancel</button><button class="btn btn-primary">Save entry</button></div></form>`,fd=>{const value=Object.fromEntries(fd);if(!record.id)value.id=uid('tt');record.id?editRecord('timetable',record.id,value,'Updated timetable entry'):addRecord('timetable',value,'Added timetable entry')});}
function timetablePage(){const days=['Monday','Tuesday','Wednesday','Thursday','Friday'];return heading('Timetable','Plan the weekly rhythm for every class.','<button class="btn btn-primary" data-action="add-timetable">＋ Add entry</button>')+`<div class="timetable-grid">${days.map(day=>`<div class="day-column"><h4>${day}</h4>${db.timetable.filter(x=>x.day===day).sort((a,b)=>a.time.localeCompare(b.time)).map(x=>`<div class="slot"><strong>${esc(x.time)} · ${esc(subjectName(x.subjectId))}</strong><span>${esc(className(x.classId))} · ${esc(teacherName(x.teacherId))}</span><div class="row-actions"><button class="action-btn" data-action="edit-timetable" data-id="${x.id}">Edit</button><button class="action-btn" data-action="delete-timetable" data-id="${x.id}">×</button></div></div>`).join('')||'<div class="empty">No classes</div>'}</div>`).join('')}</div>`;}
function announcementForm(record={}){modal(record.id?'Edit announcement':'Add announcement',`<form><p class="error"></p><div class="form-grid">${field('Title','title',record.title)}${field('Date','date',record.date||today(),'date')}<div class="form-group full"><label>Message *</label><textarea name="message" required>${esc(record.message)}</textarea></div></div><div class="form-actions"><button type="button" class="btn btn-secondary" data-close-modal>Cancel</button><button class="btn btn-primary">Save announcement</button></div></form>`,fd=>{const value=Object.fromEntries(fd);if(!record.id)value.id=uid('an');record.id?editRecord('announcements',record.id, value,`Updated announcement ${value.title}`):addRecord('announcements',value,`Published announcement ${value.title}`)});}
function announcementsPage(){return heading('Announcements','Publish clear updates for families and staff.','<button class="btn btn-primary" data-action="add-announcement">＋ Add announcement</button>')+`<div class="grid-2">${card('Published updates',db.announcements.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(a=>`<div class="announcement-item"><strong>${esc(a.title)}</strong><p>${esc(a.message)}</p><span class="meta">${formatDate(a.date)}</span><div class="row-actions"><button class="action-btn" data-action="edit-announcement" data-id="${a.id}">Edit</button><button class="action-btn" data-action="delete-announcement" data-id="${a.id}">Delete</button></div></div>`).join('')||empty())}${card('Publishing note','Announcements appear on the dashboard automatically. Keep messages short and action-oriented.')}</div>`;}
function reportsPage(){return heading('Reports','Generate printable operational reports from live local data.','<button class="btn btn-primary" data-action="print-report">▣ Print report</button>')+`<div class="notice">Reports use the current records in localStorage. Use your browser print dialog to save a PDF or send to a printer.</div><div class="stats-grid"><div class="stat-card"><div class="stat-top">Student report</div><div class="stat-value">${db.students.length}</div><div class="subtext">enrolled students</div></div><div class="stat-card"><div class="stat-top">Teacher report</div><div class="stat-value">${db.teachers.length}</div><div class="subtext">active teachers</div></div><div class="stat-card"><div class="stat-top">Results report</div><div class="stat-value">${db.results.length}</div><div class="subtext">marks recorded</div></div><div class="stat-card"><div class="stat-top">Fees report</div><div class="stat-value">${money(db.fees.reduce((a,x)=>a+x.paid,0))}</div><div class="subtext">collected</div></div></div><div class="panel" id="reportPrint"><div class="panel-header"><h3>${esc(db.settings.schoolName)} · Student and fee overview</h3></div><div class="panel-body"><h4>Students</h4><div class="table-wrap"><table><thead><tr><th>Name</th><th>ID</th><th>Class</th><th>Guardian</th></tr></thead><tbody>${db.students.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.studentId)}</td><td>${esc(className(s.classId))}</td><td>${esc(s.guardian)}</td></tr>`).join('')}</tbody></table></div><h4>Fees</h4><div class="table-wrap"><table><thead><tr><th>Student</th><th>Total</th><th>Paid</th><th>Balance</th></tr></thead><tbody>${db.fees.map(f=>`<tr><td>${esc(studentName(f.studentId))}</td><td>${money(f.total)}</td><td>${money(f.paid)}</td><td>${money(f.total-f.paid)}</td></tr>`).join('')}</tbody></table></div></div></div>`;}
function settingsPage(){const s=db.settings;const logo=s.logo || 'assets/tayo-academy-logo.jpeg';return heading('Settings','Personalize the school workspace and appearance.','<button class="btn btn-primary" data-action="save-settings">Save settings</button>')+`<div class="settings-layout"><div class="panel settings-menu"><button class="active">School profile</button><button>Appearance</button><button>Data storage</button></div><div class="panel"><div class="panel-header"><h3>School profile</h3></div><div class="panel-body"><form id="settingsForm"><p class="error"></p><div class="form-grid">${field('School name','schoolName',s.schoolName)}${field('School phone','schoolPhone',s.schoolPhone,'tel',true,'pattern="[0-9+() .-]{7,}"')}${field('School address','schoolAddress',s.schoolAddress)}<div class="form-group"><label>Theme</label><select name="theme"><option value="light" ${s.theme==='light'?'selected':''}>Light mode</option><option value="dark" ${s.theme==='dark'?'selected':''}>Dark mode</option></select></div><div class="form-group full"><label>School logo</label><input type="file" name="logoFile" accept="image/*"><span class="subtext">Stored locally in this browser.</span><img class="logo-preview" src="${esc(logo)}" alt="School logo"></div></div><div class="form-actions"><button class="btn btn-primary">Save settings</button></div></form><hr><h3>Data storage</h3><p class="subtext">Your records are stored locally in this browser. Export or reset them for this device.</p><div class="actions"><button class="btn btn-secondary" data-action="export-data">Export JSON</button><button class="btn btn-danger" data-action="reset-data">Reset all data</button></div></div></div></div>`;}
function renderPage(){if(!canAccess(page))return accessDenied();return ({dashboard:dashboard,students:studentsPage,teachers:teachersPage,classes:classesPage,subjects:subjectsPage,attendance:attendancePage,results:resultsPage,fees:feesPage,timetable:timetablePage,announcements:announcementsPage,reports:reportsPage,settings:settingsPage,pendingAccounts:pendingAccountsPage,assignments:assignmentsPage,onlineExams:onlineExamsPage,analytics:analyticsPage,auditLog:auditLogPage,studentDashboard:studentDashboardPage,studentProfile:studentProfilePage,studentResults:studentResultsPage,studentAttendance:studentAttendancePage,studentAssignments:studentAssignmentsPage,studentExams:studentExamsPage,studentTimetable:studentTimetablePage,studentFees:studentFeesPage,studentAnnouncements:studentAnnouncementsPage,studentNotifications:studentNotificationsPage,pendingAccount:pendingAccountPage}[page]||dashboard)();}
function viewDetails(type,id){const x=get(type,id);if(type==='students'){const records=db.attendance.flatMap(a=>Object.entries(a.records).filter(([studentId])=>studentId===id).map(([,status])=>status));const present=records.filter(s=>s==='present').length,attendance=records.length?Math.round((present/records.length)*100):0;const marks=db.results.filter(r=>r.studentId===id).map(r=>r.marks),average=marks.length?Math.round(marks.reduce((a,b)=>a+b,0)/marks.length):0;modal('Student profile',`<div class="profile-header"><div class="profile-photo">${initials(x.name)}</div><div><h3>${esc(x.name)}</h3><p class="subtext">${esc(x.studentId)} · ${esc(className(x.classId))}</p></div></div><div class="kpi-row"><div class="kpi"><span>Age</span><strong>${ageFromDob(x.dob)}</strong></div><div class="kpi"><span>Attendance</span><strong>${attendance}%</strong></div><div class="kpi"><span>Average grade</span><strong>${average||'-'}</strong></div><div class="kpi"><span>Status</span><strong>Active</strong></div></div><div class="kpi-row"><div class="kpi"><span>Gender</span><strong>${esc(x.gender)}</strong></div><div class="kpi"><span>Guardian</span><strong>${esc(x.guardian)}</strong></div><div class="kpi"><span>Contact</span><strong>${esc(x.parentPhone)}</strong></div></div><div class="form-actions"><button class="btn btn-secondary" data-close-modal>Close</button></div>`,()=>{});return;}const labels=Object.entries(x).filter(([key])=>key!=='id'&&key!=='classIds').map(([key,value])=>`<div class="kpi"><span>${key}</span><strong>${esc(Array.isArray(value)?value.join(', '):value)}</strong></div>`).join('');modal('Record details',`<div class="kpi-row">${labels}</div><div class="form-actions"><button class="btn btn-secondary" data-close-modal>Close</button></div>`,()=>{});}
function bindPage(){ $$('[data-close-modal]').forEach(x=>x.onclick=closeModal); const search=$('#tableSearch'); if(search)search.oninput=filterRows; ['classFilter','genderFilter','teacherSubjectFilter','teacherClassFilter','resultClassFilter','feeFilter'].forEach(id=>{const control=$('#'+id);if(control)control.onchange=filterRows;}); const auditSearch=$('#auditSearch'),auditRole=$('#auditRoleFilter');if(auditSearch)auditSearch.oninput=filterAudit; if(auditRole)auditRole.onchange=filterAudit; const ad=$('#attendanceDate'),ac=$('#attendanceClass');if(ad)ad.onchange=()=>{shell(renderPage());bindPage()};if(ac)ac.onchange=()=>{shell(renderPage());bindPage()}; $$('.attendance-status').forEach(x=>x.onchange=()=>{}); $$('[data-action]').forEach(button=>button.onclick=handleAction); const settings=$('#settingsForm');if(settings)settings.onsubmit=saveSettings; }
function filterRows(){const query=($('#tableSearch')?.value||'').toLowerCase(), cls=$('#classFilter')?.value||$('#teacherClassFilter')?.value||$('#resultClassFilter')?.value||'', gender=$('#genderFilter')?.value||'', subject=$('#teacherSubjectFilter')?.value||'', status=$('#feeFilter')?.value||'';$$('#dataTable tbody tr').forEach(row=>{const okay=(!query||(row.dataset.search||'').includes(query))&&(!cls||row.dataset.class===cls)&&(!gender||row.dataset.gender===gender)&&(!subject||row.dataset.subject===subject)&&(!status||row.dataset.status===status);row.style.display=okay?'':'none';});}
function filterAudit(){const query=($('#auditSearch')?.value||'').toLowerCase(),role=$('#auditRoleFilter')?.value||'';$$('#auditTable tbody tr').forEach(row=>row.style.display=(!query||(row.dataset.search||'').includes(query))&&(!role||row.dataset.role===role)?'':'none');}
function actionAllowed(action){if(action==='logout')return true;if(isRole('Admin'))return true;if(isRole('Teacher'))return ['mark-all','save-attendance','load-attendance','add-result','edit-result','delete-result','create-assignment','view-submissions','create-exam'].includes(action);if(isRole('Student'))return ['submit-assignment','take-exam','read-notification','clear-notification','mark-all-notifications'].includes(action);return false;}
function updateNotification(id,updates){const item=get('notifications',id);if(!item||item.studentId!==studentForCurrentUser()?.id)return;Object.assign(item,updates);save('notifications');refreshPage();}
function handleAction(e){const action=e.currentTarget.dataset.action,id=e.currentTarget.dataset.id;if(!actionAllowed(action)){showToast('Your role cannot perform this action.');return;}if(action==='logout'){signOut();return;}if(action==='view-pending-account'){viewPendingAccount(id);return;}if(action==='approve-account'){approveStudentAccount(id);return;}if(action==='reject-account'){rejectStudentAccount(id);return;}if(action==='read-notification'){updateNotification(id,{read:true});return;}if(action==='clear-notification'){updateNotification(id,{cleared:true});return;}if(action==='mark-all-notifications'){studentNotifications().forEach(item=>item.read=true);save('notifications');refreshPage();return;}if(action==='create-assignment')assignmentForm();if(action==='submit-assignment')submissionForm(id);if(action==='view-submissions')showSubmissions(id);if(action==='create-exam')examForm();if(action==='take-exam')takeExam(id); if(action==='add-student')studentForm();if(action==='edit-student')studentForm(get('students',id));if(action==='delete-student')removeRecord('students',id,'student');if(action==='view-student')viewDetails('students',id);if(action==='add-teacher')teacherForm();if(action==='edit-teacher')teacherForm(get('teachers',id));if(action==='delete-teacher')removeRecord('teachers',id,'teacher');if(action==='view-teacher')viewDetails('teachers',id);if(action==='add-class')classForm();if(action==='edit-class')classForm(get('classes',id));if(action==='delete-class')removeRecord('classes',id,'class');if(action==='add-subject')subjectForm();if(action==='edit-subject')subjectForm(get('subjects',id));if(action==='delete-subject')removeRecord('subjects',id,'subject');if(action==='add-result')resultForm();if(action==='edit-result')resultForm(get('results',id));if(action==='delete-result')removeRecord('results',id,'result');if(action==='add-fee')feeForm();if(action==='edit-fee')feeForm(get('fees',id));if(action==='delete-fee')removeRecord('fees',id,'fee record');if(action==='view-fee')viewDetails('fees',id);if(action==='add-timetable')timetableForm();if(action==='edit-timetable')timetableForm(get('timetable',id));if(action==='delete-timetable')removeRecord('timetable',id,'timetable entry');if(action==='add-announcement')announcementForm();if(action==='edit-announcement')announcementForm(get('announcements',id));if(action==='delete-announcement')removeRecord('announcements',id,'announcement');if(action==='mark-all')$$('.attendance-status').forEach(x=>x.value=e.currentTarget.dataset.status);if(action==='save-attendance')saveAttendance();if(action==='load-attendance'){ $('#attendanceDate').value=e.currentTarget.dataset.date;$('#attendanceClass').value=e.currentTarget.dataset.class;shell(renderPage());bindPage();}if(action==='print-report')window.print();if(action==='export-data')exportData();if(action==='reset-data')resetData();}
function saveAttendance(){const date=$('#attendanceDate').value,classId=$('#attendanceClass').value,records={};$$('.attendance-status').forEach(x=>records[x.dataset.student]=x.value);const old=db.attendance.find(x=>x.date===date&&x.classId===classId);if(old)old.records=records;else db.attendance.push({id:uid('a'),date,classId,records});save('attendance');logActivity(`Saved attendance for ${className(classId)}`);showToast('Attendance saved');shell(renderPage());bindPage();}
function saveSettings(e){e.preventDefault();const fd=new FormData(e.currentTarget), value=Object.fromEntries(fd);const file=fd.get('logoFile');const finish=logo=>{db.settings={...db.settings,schoolName:value.schoolName,schoolPhone:value.schoolPhone,schoolAddress:value.schoolAddress,theme:value.theme,logo:logo||db.settings.logo};save('settings');logActivity('Updated school settings');showToast('Settings saved');shell(renderPage());bindPage();};if(file&&file.size){const reader=new FileReader();reader.onload=()=>finish(reader.result);reader.readAsDataURL(file);}else finish();}
function exportData(){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='schoolos-backup.json';a.click();URL.revokeObjectURL(url);showToast('Backup downloaded');}
function resetData(){if(!confirm('Reset all records to the starter dataset?'))return;Object.assign(db,structuredClone(seed));saveAll();showToast('Data reset');shell(renderPage());bindPage();}
initData();
if(page==='login') loginPage();
else if(!currentUser()) location.replace('login.html');
else if(isRole('Student')&&currentUser().status==='Pending Verification'&&page!=='pendingAccount') location.replace('pending-account.html');
else if(isRole('Student')&&!canAccess(page)) location.replace('student-dashboard.html');
else { shell(renderPage()); bindPage(); }
